import{_ as s,o as t,c as e,a4 as a}from"./chunks/framework.vNSRaLQv.js";const _=JSON.parse('{"title":"WinSxS 是系统组件库，绝对不能删","description":"","frontmatter":{"title":"WinSxS 是系统组件库，绝对不能删","date":"2026-07-18T00:00:00.000Z"},"headers":[],"relativePath":"posts/血的教训-WinSxS.md","filePath":"posts/血的教训-WinSxS.md"}'),n={name:"posts/血的教训-WinSxS.md"};function l(o,i,p,r,d,S){return t(),e("div",null,[...i[0]||(i[0]=[a('<h1 id="winsxs-是系统组件库-绝对不能删" tabindex="-1">WinSxS 是系统组件库，绝对不能删 <a class="header-anchor" href="#winsxs-是系统组件库-绝对不能删" aria-label="Permalink to &quot;WinSxS 是系统组件库，绝对不能删&quot;">​</a></h1><p>WinSxS (Windows Side-by-Side) 是 Windows 的系统组件存储库。</p><p>里面存着所有系统组件的<strong>原始文件副本</strong>，包括：</p><ul><li>内核文件</li><li>DLL 动态链接库</li><li>系统关键二进制</li></ul><p><strong>删掉 WinSxS 的后果：</strong></p><ul><li>开机黑屏，只有鼠标指针能移动</li><li>任务管理器打不开（Ctrl+Alt+Del 无效）</li><li>任何系统功能都无法使用</li><li>无法恢复，只能重装系统</li></ul><p>看似 WinSxS 占空间很大（几 GB 到十几 GB），那是因为系统用硬链接让它看起来大， 实际占用远没显示的大。<strong>Windows 自带的「磁盘清理」工具可以安全压缩 WinSxS， 但绝不要手动删除 WinSxS 目录。</strong></p><p>正确清理方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>开始菜单 → 磁盘清理 → 清理系统文件</span></span></code></pre></div>',9)])])}const x=s(n,[["render",l]]);export{_ as __pageData,x as default};
